  "content": "1|import type { ApplicationScopeRef } from '../../api/contracts/appendoo/applicationScope.types';
2|import type { ContextPack } from '../../api/contracts/appendoo/contextPack.types';
3|import type {
4|  AppEndooSemanticPlan,
5|  BuildSemanticPlanInput,
6|  SemanticPlanArtifact,
7|} from '../../api/contracts/appendoo/semanticPlan.types';
8|import { SEMANTIC_PLAN_COMPILER_VERSION } from '../../api/contracts/appendoo/semanticPlan.types';
9|import { detectUIIntent } from '../detectCodingIntent';
10|import { compileChangeGraphScaffold } from './engineeringWorkspaceScaffold';
11|import type { PlanningBlocker } from '../../api/contracts/appendoo/semanticPlanAuthority.types';
12|import {
13|  buildCompositionCandidates,
14|  computeReuseSummary,
15|  validateSemanticPlanScaffold,
16|} from './semanticPlanCompositionScaffold';
17|import { buildServerFunctionUiPlan } from './serverFunctionUiPlanner';
18|import { buildCreateServerFunctionPlan } from './createServerFunctionPlanner';
19|import { computeEvidenceMetrics } from './semanticPlanAuthorityGates';
20|
21|const buildPlanId = (contextPackId: string): string => `asp:${contextPackId}:${Date.now()}`;
22|
23|const slugifyUiTarget = (functionRef: string): string => (
24|  `${functionRef.trim().toLowerCase().replace(/\./g, '-').replace(/[^a-z0-9-]+/g, '-').replace(/^-+|-+$/g, '')}-calculator`
25|);
26|
27|const buildArtifactsFromContext = (
28|  contextPack: ContextPack,
29|  userPrompt?: string,
30|): SemanticPlanArtifact[] => {
31|  const functionTarget = contextPack.primaryTargets.find((target) => target.kind === 'function');
32|  const uiIntent = Boolean(userPrompt?.trim() && detectUIIntent(userPrompt));
33|
34|  if (uiIntent && functionTarget?.ref?.trim()) {
35|    const functionRef = functionTarget.ref.trim();
36|    const uiTargetRef = slugifyUiTarget(functionRef);
37|    return [{
38|      artifactId: `artifact:page:${uiTargetRef}`,
39|      kind: 'page',
40|      title: `UI for ${functionTarget.label || functionRef}`,
41|      action: 'create',
42|      targetRef: uiTargetRef,
43|      evidenceIds: [
44|        functionTarget.targetId,
45|        `function:${functionRef}`,
46|      ],
47|    }];
48|  }
49|
50|  const artifacts: SemanticPlanArtifact[] = contextPack.primaryTargets.map((target) => ({
51|    artifactId: `artifact:${target.targetId}`,
52|    kind: target.kind === 'function'
53|      ? 'server_function'
54|      : target.kind === 'page'
55|        ? 'page'
56|        : target.kind === 'component'
57|          ? 'component'
58|          : 'configuration',
59|    title: target.label,
60|    action: 'modify',
61|    targetRef: target.ref,
62|    evidenceIds: contextPack.selectionExplanations
63|      .filter((explanation) => explanation.evidenceId === target.targetId)
64|      .map((explanation) => explanation.evidenceId),
65|  }));
66|
67|  if (artifacts.length === 0 && userPrompt?.trim()) {
68|    artifacts.push({
69|      artifactId: 'artifact:prompt-derived',
70|      kind: 'configuration',
71|      title: userPrompt.trim().slice(0, 120),
72|      action: 'modify',
73|      evidenceIds: [],
74|    });
75|  }
76|
77|  return artifacts;
78|};
79|
80|const buildScaffoldBlockingIssues = (): PlanningBlocker[] => ([{
81|  code: 'PLANNING_NOT_IMPLEMENTED',
82|  stage: 'PLANNING',
83|  materiality: 'BLOCKING',
84|  evidenceRefs: [],
85|}]);
86|
87|/**
88| * Primary planner entry — authoritative vertical-slice planners first, scaffold only as
89| * non-authoritative fallback. V5 P06 § 8.2/EV-1 added `buildCreateServerFunctionPlan` as a
90| * second authoritative path (existing-function→UI was the only one before this phase) so that
91| * "create a new server function" no longer falls through to the scaffold.
92| */
93|export const buildSemanticPlan = (input: BuildSemanticPlanInput): AppEndooSemanticPlan => {
94|  const verticalSlicePlan = buildServerFunctionUiPlan(input) ?? buildCreateServerFunctionPlan(input);
95|  if (verticalSlicePlan) {
96|    return {
97|      ...verticalSlicePlan,
98|      evidenceMetrics: computeEvidenceMetrics(verticalSlicePlan),
99|    };
100|  }
101|  return buildSemanticPlanScaffold(input);
102|};
103|
104|/** AE-6.2 scaffold — ASP from ContextPack + scope with composition and validation depth. */
105|export const buildSemanticPlanScaffold = (input: BuildSemanticPlanInput): AppEndooSemanticPlan => {
106|  const scopeKey = input.applicationScope?.scopeKey ?? input.contextPack.applicationScopeRef;
107|  const proposedArtifacts = buildArtifactsFromContext(input.contextPack, input.userPrompt);
108|  const changeSetId = `cs:${input.contextPack.contextPackId}`;
109|  const compositionCandidates = buildCompositionCandidates(input.contextPack, input.userPrompt);
110|
111|  const basePlan: AppEndooSemanticPlan = {
112|    planId: buildPlanId(input.contextPack.contextPackId),
113|    revision: 1,
114|    applicationScopeRef: scopeKey,
115|    contextPackId: input.contextPack.contextPackId,
116|    objective: input.userPrompt?.trim() || 'Implement the requested engineering change',
117|    scope: scopeKey,
118|    resolvedTargets: input.contextPack.primaryTargets.map((target) => target.targetId),
119|    requirements: input.contextPack.governance,
120|    assumptions: [],"
}
